import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"61、【中孚】 兑下巽上","description":"周易集注 - 61、【中孚】 兑下巽上","frontmatter":{"title":"61、【中孚】 兑下巽上","description":"周易集注 - 61、【中孚】 兑下巽上"},"headers":[],"relativePath":"zh/classics/jizhu/065.md","filePath":"zh/classics/jizhu/065.md"}'),l={name:"zh/classics/jizhu/065.md"};function h(t,a,s,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_61、【中孚】-兑下巽上" tabindex="-1">61、【中孚】 兑下巽上 <a class="header-anchor" href="#_61、【中孚】-兑下巽上" aria-label="Permalink to “61、【中孚】 兑下巽上”">​</a></h1><p>孚，信也。为卦二阴在内，四阳在外，而二五之阳皆得其中。以一卦六爻言之，为中虚;以二体之二五言之，为中实，皆孚之象也，又下说以应上，上巽以顺下，亦有孚义，《序卦》：节而信之，故受之以中孚，所以次节。</p><p>豚鱼，生于大泽之中，将生风则先出拜，乃信之自然无所勉强者也。《唐诗》云“河豚吹浪夜还风”是也。信如豚鱼则吉矣，本卦上风下泽，豚鱼生于泽，知风，故象之。鹤知秋，鸡知旦，二物皆信，故卦爻皆象之。利贞者，利于正也。若盗贼相约，男女相私，岂不彼此有孚，然非理之正矣，故利贞。</p><p>《彖》曰：中孚，柔在内而刚得中，说而巽，孚乃化邦也。豚鱼吉，信及豚鱼也。利涉大川，乘木舟虚也。中孚以利贞，乃应乎天也。</p><p>以卦体卦德卦象释卦名卦辞。二柔在内而中虚，二刚居中而中实，虚则内欲不萌，实则外诱不入，此中孚之本体也。而又下说上顺，上下交孚，所以孚乃化邦也。若徙木立信，乃出于矫强矣，安能化邦。《易举正》止有“信及也”三字，无“豚鱼”二字。及者至也，言信至于豚鱼，则信出自然矣。如此信，此所以吉也。乘木舟虚者，本卦外实中虚，有舟虚之象。至诚以涉险，如乘巽木之空，以行乎兑泽之上，又岂有沉溺之患，所以利涉大川。应乎天者，信能正，则事事皆天理，所谓诚者天之道也。贞应乎天，所以利贞。</p><h3 id="《象》曰-泽上有风-中孚-君子以议狱缓死。" tabindex="-1">《象》曰：泽上有风，中孚，君子以议狱缓死。 <a class="header-anchor" href="#《象》曰-泽上有风-中孚-君子以议狱缓死。" aria-label="Permalink to “《象》曰：泽上有风，中孚，君子以议狱缓死。”">​</a></h3><p>圣人之于卦，以八卦为之体，其所变六十四卦中，错之综之，上之下之，皆其卦也。如火雷噬嗑，文王之意，以有火之明，雷之威，方可用狱。孔子《大象》言用狱者五，皆取雷火之意，丰取其雷火也，旅与贲，艮综震，亦雷火也，解则上雷而中爻为火也，下体错离，亦火也。此卦则大象为火，而中爻为雷也。盖孔子于易，韦编三绝，胸中之义理无穷，所以无往而非其八卦。不然，风泽之与议狱缓死何相干涉?《易经》一错一综，大象中爻，观此五卦，自能默悟。兑为口舌，议之象。巽为不果，缓之象。</p><p>议狱缓死者，议狱罪当死矣，乃缓其死而欲求其生也。风入水受者，中孚之象也。议狱缓死，则至诚恻怛之意溢于用刑之间矣。</p><p>初九，虞吉，有他不燕。</p><p>虞者乐也安也，燕者喜也安也，二字之义相近。有他者，其志不定而他求其所应也。本卦三四皆阴爻，六三则阴柔不正，六四则得八卦之正位者，因有此阴柔不正者隔于其中，故周公方设此有他之戒。若论本爻应爻，足不容戒也。</p><p>初九阳刚得正，而上应六四，四盖柔顺得正者也，当中孚之初，其志未变，故有与六四相信而安乐之象。占者如是则吉，若不信于六四，而别信于他，则是不能安乐其中孚矣。故戒占者如此。</p><h3 id="《象》曰-初九虞吉-志未变也。" tabindex="-1">《象》曰：初九虞吉，志未变也。 <a class="header-anchor" href="#《象》曰-初九虞吉-志未变也。" aria-label="Permalink to “《象》曰：初九虞吉，志未变也。”">​</a></h3><p>方初，中孚之志未变。</p><p>九二，鸣鹤在阴，其子和之;我有好爵，吾与尔靡之。和去声</p><p>大象离，雉象，变震，鹄象，皆飞鸟之象也。不言雉鹄而言鹤者，鹤信故也。鹤八月霜降则鸣，兑乃正秋，故以鹤言之。中孚错小过之遗音，又兑为口舌，鸣之象也。故谦豫二卦，象小过皆言鸣。在阴者，鹤行依洲屿，不集林木，九居阴爻，在阴之象也。巽为长女，兑为少女，子母之象也。好爵者懿德也，阳德居中，故曰好爵。</p><p>子与尔皆指五<em>，因中孚感应极至，而无以加，所以不论君臣，皆呼子尔也。言懿德人之所好，故好爵虽我之所有，而彼亦系恋之也。物之相爱者若</em>如子母之同心，人之所慕者莫如好爵之可贵，鹤鸣子和者，天机之自动也。好爵尔靡者，天理之自孚也。靡与縻同，系恋也。巽为绳，系之象也。</p><p>九二以刚中居下，有中孚之实。而九五刚中居上，亦以中孚之实应之，故有此象。占者有是德，方有是感应也。</p><ul><li><p>原文阙“子”字，依他本补。</p></li><li><p>若或作“莫”。</p></li></ul><h3 id="《象》曰-其子和之-中心愿也。" tabindex="-1">《象》曰：其子和之，中心愿也。 <a class="header-anchor" href="#《象》曰-其子和之-中心愿也。" aria-label="Permalink to “《象》曰：其子和之，中心愿也。”">​</a></h3><p>诚意所愿，非九二求于九五也。</p><p>六三，得敌，或鼓或罢，或泣或歌。</p><p>得敌者，得对敌也，指上九之应也。言六三不正，上九亦不正也。阴阳皆位不当，所以曰得敌。巽为进退，为不果，作止之象。又中爻震为鼓，鼓之象。艮为止，罢之之象。本卦大象离错坎，坎为加忧，泣之象。兑为口舌，为巫，歌之象。</p><p>六三阴柔不正，而上应九之不正，此为悦之极，彼为信之穷，皆相敌矣。是以或鼓或罢，而作止不定。或泣或歌，而哀乐无常。其象如此，占者不能孚信可知矣。</p><h3 id="《象》曰-或鼓或罢-位不当也。" tabindex="-1">《象》曰：或鼓或罢，位不当也。 <a class="header-anchor" href="#《象》曰-或鼓或罢-位不当也。" aria-label="Permalink to “《象》曰：或鼓或罢，位不当也。”">​</a></h3><p>阴居阳位。</p><p>六四，月几望，马匹亡，无咎*。</p><p>月几望者，月与日对而从乎阳也。本卦下体兑，中爻震，震东兑西，日月相对，故几望。曰几者，将望而犹未望也。因四阴爻，近五阳爻，故有此日月之象。马匹亡者，震为马，马之象也。此爻变，中爻成离牛，不成震马矣，马匹亡之象也。匹者配也，指初九也。曰亡者，不与之交，而绝其类也。无咎者心事光明也。</p><p>六四当中孚之时，近君之位，柔顺得正，而中孚之实德，惟精白以事君，不系恋其党与者也，故有月几望马匹亡之象。占者能是，则无咎矣。</p><ul><li>原文阙“无”字。</li></ul><h3 id="《象》曰-马匹亡-绝类上也。" tabindex="-1">《象》曰：马匹亡，绝类上也。 <a class="header-anchor" href="#《象》曰-马匹亡-绝类上也。" aria-label="Permalink to “《象》曰：马匹亡，绝类上也。”">​</a></h3><p>绝其类应而上从五也。</p><p>九五，有孚挛如，无咎。</p><p>挛如，即鹤鸣子和，我爵尔靡也。靡字与挛字，皆有固结而不可解之意。縻者系恋也，挛者相连也。如合九二，共成一体。包二阴以成中孚，故有此象。若以人事论，乃委用专，而信任笃，虞庭之赓歌，有商之一德是也。无咎者，上下交而德业成也。</p><p>九五居尊位，为中孚之主，刚健中正，有中孚之实德，而下应九二，与之同德相信，故其象占如此。</p><h3 id="《象》曰-有孚挛如-位正当也。" tabindex="-1">《象》曰：有孚挛如，位正当也。 <a class="header-anchor" href="#《象》曰-有孚挛如-位正当也。" aria-label="Permalink to “《象》曰：有孚挛如，位正当也。”">​</a></h3><p>与履不同，履周公爻辞乃贞厉，此则无咎。</p><p>上九，翰音登于天，贞凶。</p><p>《礼记》鸡曰翰音，而此亦曰翰音者，以巽为鸡也。因错小过，飞鸟遗之音，故九二曰鹤鸣，而此曰翰音也。鸡信物，天将明则鸣，有中孚之意。巽为高，登天之象也。又居天位，亦登天之象也。《礼记》注：翰长也。鸡肥则音长。考诸韵，无长字之义，盖翰羽也，鸡鸣则振拍其羽，故曰翰音，则翰音即鸡鸣二字也。登者升也，言鸡鸣之声，登闻于天也。鸡鸣本信，但鸣未几而天明，不能信之长久。巽进退不果，不长久之象也。九二上孚于五，在阴而子和，上九不下孚于三，翰音反登天，其道盖相反矣。贞者信，本正理也。</p><p>上九居中孚之极，极则中孚变矣。盖声闻过情，不能长久于中孚者也，故有此象。占者得此，贞亦凶矣。</p><h3 id="《象》曰-翰音登于天-何可长也。" tabindex="-1">《象》曰：翰音登于天，何可长也。 <a class="header-anchor" href="#《象》曰-翰音登于天-何可长也。" aria-label="Permalink to “《象》曰：翰音登于天，何可长也。”">​</a></h3><p>言不能鸣之长登于天，不过天将明，一时而已。</p>',41)])])}const m=e(l,[["render",h]]);export{_ as __pageData,m as default};
